/*! Cloudflare Email Decode - v0.1 */
(function(){
  "use strict";
  function decodeEmail(encodedString) {
    var email = "", r = parseInt(encodedString.substr(0, 2), 16), n, i;
    for (i = 2; encodedString.length - i; i += 2) {
      n = parseInt(encodedString.substr(i, 2), 16) ^ r;
      email += String.fromCharCode(n);
    }
    return email;
  }

  function replaceEmails() {
    var elements = document.querySelectorAll("a.__cf_email__");
    for (var i = 0; i < elements.length; i++) {
      var el = elements[i];
      var encoded = el.getAttribute("data-cfemail");
      if (encoded) {
        var email = decodeEmail(encoded);
        el.setAttribute("href", "mailto:" + email);
        el.textContent = email;
      }
    }
  }

  document.addEventListener("DOMContentLoaded", replaceEmails);
})();
